 function interact(){if(!state.started){welcome();return}if(state.battle)return;let p=state.player;if(p.x===2&&p.y===4){state.area=(state.area+1)%3;state.player={x:8,y:5};updateUI();toast(`A friendly boat to ${areas[state.area].name}!`);return}if(p.x===9&&p.y===6){rest();return}if(Math.random()<.55){let arr=areas[state.area].creatures; battle(arr[Math.floor(Math.random()*arr.length)])}else toast('A warm breeze rustles the leaves. You hear a distant spirit song.')}
 $('interactBtn').onclick=interact;
 function rest(){if(state.party.length){state.party.forEach(m=>m.hp=m.maxhp);updateUI();toast('Tea, sweet banana, and a full rest. Everyone feels better!')}else toast('The tea keeper smiles. Choose a companion first!')}
 $('restBtn').onclick=rest;
-$('bagBtn').onclick=()=>open(`<button class="close" onclick="document.getElementById('modal').classList.remove('open')">×</button><div class="eyebrow">Wayfinder satchel</div><h1>Little offerings</h1><div class="journal-entry"><span class="emoji">🔮</span><div><strong>Sea-glass beads × ${state.orbs}</strong><small>Offer a bead to a spirit you meet. Kindness works better than force.</small></div></div><p>Beads are gifts, not traps. If someone would rather be alone, respect their answer and meet them again another day.</p><button class="primary" id="bagclose">Close satchel</button>`);setTimeout(()=>{let b=$('bagclose');if(b)b.onclick=close},0)};
+$('bagBtn').onclick=()=>{open(`<button class="close" onclick="document.getElementById('modal').classList.remove('open')">×</button><div class="eyebrow">Wayfinder satchel</div><h1>Little offerings</h1><div class="journal-entry"><span class="emoji">🔮</span><div><strong>Sea-glass beads × ${state.orbs}</strong><small>Offer a bead to a spirit you meet. Kindness works better than force.</small></div></div><p>Beads are gifts, not traps. If someone would rather be alone, respect their answer and meet them again another day.</p><button class="primary" id="bagclose">Close satchel</button>`);setTimeout(()=>{let b=$('bagclose');if(b)b.onclick=close},0)};
 function guide(){let entries=[...starters,...Object.values(mons)].filter(m=>state.seen.includes(m.name));open(`<button class="close" onclick="document.getElementById('modal').classList.remove('open')">×</button><div class="eyebrow">Field guide · ${state.seen.length} stories collected</div><h1>Island bestiary</h1><p>Folklore travels across shorelines. These gentle new friends carry stories that belong to living cultures.</p><div class="tabs"><button class="tab on" data-tab="all">All stories</button><button class="tab" data-tab="indonesia">Indonesia</button><button class="tab" data-tab="malaysia">Malaysia</button><button class="tab" data-tab="singapore">Singapore</button></div><div class="journal-list">${entries.length?entries.map(m=>`<div class="journal-entry"><span class="emoji">${m.emoji}</span><div><strong>${m.name}</strong><small>${m.type} spirit · ${areas.find(a=>a.creatures.includes(m.name))?.sub||'Your first companion'}</small><small style="font:400 10px 'DM Sans';line-height:1.4;margin-top:5px;color:#708078">${m.lore}</small></div></div>`).join(''):'<div class="empty-party">No stories collected yet. Follow the path, and keep a kind heart.</div>'}</div><p class="modal-foot">Folklore varies by community and storyteller. This game is an original, respectful interpretation—not a definitive cultural account.</p>`);$('dialog').querySelectorAll('[data-tab]').forEach(t=>t.onclick=()=>{document.querySelectorAll('.tab').forEach(x=>x.classList.remove('on'));t.classList.add('on');if(t.dataset.tab!=='all')toast('Stories are gathered across the whole archipelago.')})}
 $('guideBtn').onclick=guide;$('journalOpen').onclick=guide;
 $('soundBtn').onclick=()=>{state.sound=!state.sound;$('soundBtn').textContent=state.sound?'♫':'♪';toast(state.sound?'Island sounds on':'Island sounds off')};
 resize();welcome();

