 function open(content){$('dialog').innerHTML=content;$('modal').classList.add('open');$('modal').scrollTop=0}function close(){if(state.battle)return;$('modal').classList.remove('open')}
 $('modal').addEventListener('click',e=>{if(e.target===$('modal'))close()});
 function startGame(starter){state.started=true;state.train=document.getElementById('nameInput')?.value.trim()||'Rimba';$('trainerName').textContent=state.train;let s={...starter,hp:starter.hp,maxhp:starter.hp,level:3};state.party=[s];state.seen.push(s.name);updateUI();$('modal').classList.remove('open');toast(`${s.name} joined your journey!`)}
 function welcome(){open(`<div class="intro-mark">🌴✨</div><div class="eyebrow">A small adventure through living folklore</div><h1>Isles of Myth</h1><p>Across Indonesia, Malaysia, and Singapore, old stories still bloom. Walk the island paths, meet the spirits, and collect their stories in your field guide.</p><label class="eyebrow" for="nameInput">YOUR WAYFINDER NAME</label><input id="nameInput" maxlength="12" placeholder="Rimba" style="display:block;width:100%;margin-top:6px;padding:11px;border:1px solid #e4ddc6;border-radius:10px;background:#fffdf5;font:600 13px 'DM Sans';color:#214346"><h3 style="font:800 15px Fraunces;margin:19px 0 0">Choose a first companion</h3><div class="starter-grid">${starters.map((s,i)=>`<button class="starter" data-starter="${i}"><span class="emoji">${s.emoji}</span><strong>${s.name}</strong><small>${s.type} · Lv. 3</small><p>${s.lore}</p></button>`).join('')}</div><p class="modal-foot">A gentle, original folklore-inspired adventure. Inspired by stories from across the region.</p>`);$('dialog').querySelectorAll('[data-starter]').forEach(b=>b.onclick=()=>startGame(starters[+b.dataset.starter]))}
-function battle(encounter){if(state.busy||!state.party.length)return;state.busy=true;let base=mons[encounter];let foe={...base,hp:base.hp,maxhp:base.hp};state.battle={foe,log:`A wild ${foe.name} is curious about you!`};renderBattle()}
+function battle(encounter){if(state.busy||!state.party.length)return;let base=mons[encounter];let foe={...base,hp:base.hp,maxhp:base.hp};state.battle={foe,log:`A wild ${foe.name} is curious about you!`};renderBattle()}
 function renderBattle(){if(!state.battle)return;let {foe,log}=state.battle,active=state.party[0];open(`<div class="eyebrow">A little encounter · ${foe.type}</div><h1>Someone is here!</h1><div class="battle"><div class="battlemon"><span class="emoji">${active.emoji}</span><strong>${active.name}</strong><div class="battlebar"><i style="width:${active.hp/active.maxhp*100}%"></i></div><small style="font:500 8px 'DM Mono'">${active.hp} / ${active.maxhp} HP</small></div><div class="vs">✦ &nbsp;VS&nbsp; ✦</div><div class="battlemon"><span class="emoji">${foe.emoji}</span><strong>${foe.name}</strong><div class="battlebar"><i style="width:${foe.hp/foe.maxhp*100}%"></i></div><small style="font:500 8px 'DM Mono'">${foe.hp} / ${foe.maxhp} HP</small></div></div><div class="battlelog">${log}</div><div class="move-grid">${active.moves.map((m,i)=>`<button class="move" data-move="${i}" ${state.battle.turn?'disabled':''}>${m[0]}<small>${m[1]} · ${m[2]} power</small></button>`).join('')}</div><div class="battle-actions"><button class="primary" id="captureBtn">✦ &nbsp;Offer a bead (${state.orbs})</button><button class="runbtn" id="runBtn">Give them space</button></div>`);$('dialog').querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>attack(+b.dataset.move));$('captureBtn').onclick=capture;$('runBtn').onclick=run;updateUI()}
 function attack(i){let b=state.battle;if(!b||state.busy)return;state.busy=true;const m=state.party[0],move=m.moves[i];let dmg=move[2]+Math.floor(Math.random()*5);b.foe.hp=Math.max(0,b.foe.hp-dmg);b.log=`${m.name} used ${move[0]}! The ${b.foe.name} glimmers in surprise.`;if(b.foe.hp<=0){b.log=`${b.foe.name} trusts you now. Offer a bead to invite them along!`;state.busy=false;renderBattle();return}b.turn=true;renderBattle();setTimeout(()=>{if(!state.battle)return;let foe=state.battle.foe,hit=4+Math.floor(Math.random()*5);m.hp=Math.max(1,m.hp-hit);state.battle.turn=false;state.battle.log=`${foe.name} answered with a gentle ${foe.moves[0][0]}! ${m.name} lost ${hit} energy.`;state.busy=false;updateUI();renderBattle()},700)}
 function capture(){let b=state.battle;if(!b)return;if(state.orbs<=0){state.battle.log='Your satchel is out of offering beads. Visit the tea stall for more.';renderBattle();return}state.orbs--;let chance=b.foe.hp<b.foe.maxhp*.55?.86:.61;if(Math.random()<chance){if(state.party.length>=4){state.battle.log=`${b.foe.name} is glad to meet you, but your party is full. Visit your guide to make room.`;state.orbs++;renderBattle();return}let friend={...b.foe,hp:b.foe.maxhp,maxhp:b.foe.maxhp,level:2,moves:b.foe.moves};state.party.push(friend);if(!state.seen.includes(friend.name))state.seen.push(friend.name);state.beads++;state.battle=null;state.busy=false;$('modal').classList.remove('open');updateUI();toast(`${friend.name} joined your island journey!`)}else{state.battle.log=`The bead glows, then rolls away. ${b.foe.name} is still deciding...`;renderBattle()}}
 function run(){state.battle=null;state.busy=false;$('modal').classList.remove('open');toast('A quiet nod. You part as friends.');}
